diff --git a/capture/local.go b/capture/local.go
new file mode 100644
index 0000000..58dc8aa
--- /dev/null
+++ b/capture/local.go
@@ -0,0 +1,430 @@
+package capture
+
+import (
+	"context"
+	"errors"
+	"fmt"
+	"io"
+	"os"
+	"sync"
+	"time"
+
+	"github.com/charmbracelet/log"
+	"github.com/containernetworking/plugins/pkg/ns"
+	"github.com/gopacket/gopacket"
+	"github.com/gopacket/gopacket/afpacket"
+	clablabruntime "github.com/srl-labs/containerlab/labruntime"
+)
+
+const (
+	// localReorderWindow is how long the merged stream holds packets of local sockets back to
+	// write them in timestamp order. Each socket hands over its packets within
+	// localBlockTimeout, so a few times that covers the delivery skew between sockets.
+	localReorderWindow = 100 * time.Millisecond
+	// localBlockTimeout is how long the kernel fills a ring block before it hands it over.
+	localBlockTimeout = 10 * time.Millisecond
+	// localPollTimeout is how often a socket reader checks whether the capture ended.
+	localPollTimeout = 100 * time.Millisecond
+	// localReopenInterval is how often a reader tries to reopen the socket of an interface
+	// that went down or disappeared.
+	localReopenInterval = 200 * time.Millisecond
+	// localDrainQuiet is how long after the end of a capture a reader keeps waiting for packets
+	// still in the socket's ring: the kernel hands over a block within two block timeouts.
+	localDrainQuiet = 5 * localBlockTimeout
+	// localDrainTimeout bounds the drain while packets keep arriving.
+	localDrainTimeout = 250 * time.Millisecond
+	// localRingBlocks and localMinBlockSize size the receive ring of each socket: eight blocks
+	// of at least 1 MiB, each larger than the snap length.
+	localRingBlocks   = 8
+	localMinBlockSize = 1 << 20
+	// vlanHeaderLength is the length of the 802.1Q tag put back into frames whose tag the
+	// kernel moved out of band.
+	vlanHeaderLength = 4
+)
+
+// errReadTimeout is returned by a packet source that has no packet within the poll timeout.
+var errReadTimeout = errors.New("no packet within the poll timeout")
+
+// ExecFunc runs f in the network namespace of a node.
+type ExecFunc func(ctx context.Context, f func(ns.NetNS) error) error
+
+// LocalTarget is one interface of a node on this machine (Docker or Podman) to capture.
+type LocalTarget struct {
+	// Node is the node name as the topology spells it.
+	Node string
+	// Interface is the interface name inside the node.
+	Interface string
+	// Exec runs a function in the node's network namespace.
+	Exec ExecFunc
+}
+
+// packetSource reads the packets of one interface.
+type packetSource interface {
+	// ReadPacket returns the next packet; the data is only valid until the next call. It
+	// returns errReadTimeout when no packet arrived within the poll timeout.
+	ReadPacket() ([]byte, gopacket.CaptureInfo, error)
+	Close()
+}
+
+// openSourcesFunc opens one packet source per interface in the network namespace exec enters.
+type openSourcesFunc func(
+	ctx context.Context,
+	exec ExecFunc,
+	interfaces []string,
+	snapLength int,
+) ([]packetSource, error)
+
+// CaptureLocal streams pcapng from interfaces of nodes on this machine to w, with the same
+// output and end conditions as labruntime.PacketCapturer.Capture: one section, one Interface
+// Description Block per target named <node>:<interface>, then the packets of every target in
+// timestamp order. targets lists the interfaces of req.Targets, resolved, in the same order.
+//
+// Each interface is read through a packet socket opened in the node's network namespace, so
+// nothing runs in the node and the node image needs no capture tools; it needs CAP_NET_RAW and
+// the right to enter the namespace, so root. An interface that goes down is reopened once it is
+// up again; one that disappears (its node stopped or was recreated) is reattached when it is
+// back, and the time it was gone is reported as a gap through req.OnGap (or logged).
+func CaptureLocal(
+	ctx context.Context,
+	req clablabruntime.CaptureRequest,
+	targets []LocalTarget,
+	w io.Writer,
+) error {
+	return localCapture{
+		open:           openPacketSockets,
+		window:         localReorderWindow,
+		reopenInterval: localReopenInterval,
+	}.run(ctx, req, targets, w)
+}
+
+// localCapture is a local capture with its socket opener and timings, which tests replace.
+type localCapture struct {
+	open           openSourcesFunc
+	window         time.Duration
+	reopenInterval time.Duration
+}
+
+func (l localCapture) run(
+	ctx context.Context,
+	req clablabruntime.CaptureRequest,
+	targets []LocalTarget,
+	w io.Writer,
+) error {
+	if err := ValidateRequest(&req); err != nil {
+		return err
+	}
+	if len(targets) != len(req.Targets) {
+		return fmt.Errorf("capture has %d resolved targets for %d requested ones",
+			len(targets), len(req.Targets))
+	}
+
+	sources, err := l.openAll(ctx, targets, req.SnapLength)
+	if err != nil {
+		return err
+	}
+
+	names := make([]string, len(targets))
+	for idx, target := range targets {
+		names[idx] = target.Node + ":" + target.Interface
+	}
+
+	captureCtx, stop := context.WithCancel(ctx)
+	defer stop()
+	if req.Duration > 0 {
+		var cancelTimeout context.CancelFunc
+		captureCtx, cancelTimeout = context.WithTimeout(captureCtx, req.Duration)
+		defer cancelTimeout()
+	}
+
+	out, err := NewOutput(w, names, req.SnapLength, req.PacketLimit, l.window, stop)
+	if err != nil {
+		for _, source := range sources {
+			source.Close()
+		}
+
+		return err
+	}
+
+	var wg sync.WaitGroup
+	for idx, source := range sources {
+		reader := &localReader{
+			capture: l,
+			out:     out,
+			id:      uint32(idx), //nolint:gosec // bounded by the targets
+			target:  targets[idx],
+			snap:    req.SnapLength,
+			onGap:   req.OnGap,
+		}
+		wg.Go(func() {
+			reader.run(captureCtx, source)
+		})
+	}
+	wg.Wait()
+
+	return out.Close()
+}
+
+// openAll opens the sockets of every target before anything is written, one namespace entry
+// per node, so a capture that cannot start fails without output.
+func (l localCapture) openAll(
+	ctx context.Context,
+	targets []LocalTarget,
+	snapLength int,
+) ([]packetSource, error) {
+	type nodeTargets struct {
+		exec    ExecFunc
+		indexes []int
+		names   []string
+	}
+	var order []string
+	byNode := map[string]*nodeTargets{}
+	for idx, target := range targets {
+		group := byNode[target.Node]
+		if group == nil {
+			group = &nodeTargets{exec: target.Exec}
+			byNode[target.Node] = group
+			order = append(order, target.Node)
+		}
+		group.indexes = append(group.indexes, idx)
+		group.names = append(group.names, target.Interface)
+	}
+
+	sources := make([]packetSource, len(targets))
+	closeAll := func() {
+		for _, source := range sources {
+			if source != nil {
+				source.Close()
+			}
+		}
+	}
+	for _, node := range order {
+		group := byNode[node]
+		opened, err := l.open(ctx, group.exec, group.names, snapLength)
+		if err != nil {
+			closeAll()
+			return nil, fmt.Errorf("failed to start the capture on node %q: %w", node, err)
+		}
+		for idx, source := range opened {
+			sources[group.indexes[idx]] = source
+		}
+	}
+
+	return sources, nil
+}
+
+// localReader reads one interface into the merged stream.
+type localReader struct {
+	capture localCapture
+	out     *Output
+	id      uint32
+	target  LocalTarget
+	snap    int
+	onGap   func(clablabruntime.CaptureGap)
+}
+
+func (r *localReader) run(ctx context.Context, source packetSource) {
+	defer func() {
+		if source != nil {
+			source.Close()
+		}
+	}()
+
+	for {
+		if ctx.Err() != nil {
+			r.drain(source, time.Now())
+			return
+		}
+
+		data, info, err := source.ReadPacket()
+		if errors.Is(err, errReadTimeout) {
+			continue
+		}
+		if err != nil {
+			// The socket reports an error once its interface went down or was removed, and
+			// keeps reporting it: it is reopened.
+			log.Debug("Capture socket failed, reopening it", "node", r.target.Node,
+				"interface", r.target.Interface, "error", err)
+			source.Close()
+			source = r.reopen(ctx)
+			if source == nil {
+				return
+			}
+
+			continue
+		}
+
+		if more, err := r.out.Emit(r.id, r.packet(data, info)); !more || err != nil {
+			return
+		}
+	}
+}
+
+// drain writes the packets that arrived before end but were still in the socket's ring: the
+// kernel hands over a ring block once it is full or its block timeout passed, so the last
+// packets before a capture ended may not have been read yet.
+func (r *localReader) drain(source packetSource, end time.Time) {
+	deadline := end.Add(localDrainTimeout)
+	for time.Now().Before(deadline) {
+		data, info, err := source.ReadPacket()
+		if errors.Is(err, errReadTimeout) && time.Since(end) < localDrainQuiet {
+			continue
+		}
+		if err != nil || info.Timestamp.After(end) {
+			return
+		}
+		if more, err := r.out.Emit(r.id, r.packet(data, info)); !more || err != nil {
+			return
+		}
+	}
+}
+
+// packet copies a packet out of the socket's ring, cut to the snap length.
+func (r *localReader) packet(data []byte, info gopacket.CaptureInfo) *Packet {
+	length := info.Length
+	for _, ancillary := range info.AncillaryData {
+		if _, ok := ancillary.(afpacket.AncillaryVLAN); ok {
+			// the tag was put back into the data and counts toward the frame length
+			length += vlanHeaderLength
+			break
+		}
+	}
+	length = max(length, len(data))
+
+	captured := make([]byte, min(len(data), r.snap))
+	copy(captured, data)
+
+	return &Packet{
+		Timestamp:      info.Timestamp.UnixNano(),
+		OriginalLength: uint32(length), //nolint:gosec // bounded by the interface MTU
+		Data:           captured,
+	}
+}
+
+// reopen opens the interface's socket again once its node and interface are back. It returns
+// nil when the capture ended first. Time the interface could not be opened is reported as a gap;
+// an interface that only went down is not, as it has no traffic while down.
+func (r *localReader) reopen(ctx context.Context) packetSource {
+	from := time.Now()
+	var unavailable error
+
+	timer := time.NewTimer(r.capture.reopenInterval)
+	defer timer.Stop()
+
+	for {
+		select {
+		case <-ctx.Done():
+			if unavailable != nil {
+				r.reportGap(from, time.Time{}, unavailable)
+			}
+
+			return nil
+		case <-timer.C:
+		}
+
+		opened, err := r.capture.open(ctx, r.target.Exec, []string{r.target.Interface}, r.snap)
+		if err != nil {
+			if unavailable == nil {
+				log.Debug("Capture interface is not available, waiting for it",
+					"node", r.target.Node, "interface", r.target.Interface, "error", err)
+			}
+			unavailable = err
+			resetTimer(timer, r.capture.reopenInterval)
+
+			continue
+		}
+		if unavailable != nil {
+			r.reportGap(from, time.Now(), unavailable)
+		}
+
+		return opened[0]
+	}
+}
+
+func (r *localReader) reportGap(from, to time.Time, cause error) {
+	ReportGap(r.onGap, clablabruntime.CaptureGap{
+		Node:       r.target.Node,
+		Interfaces: []string{r.target.Interface},
+		From:       from,
+		To:         to,
+		Reason:     fmt.Sprintf("the interface was not available: %v", cause),
+	})
+}
+
+// openPacketSockets opens one packet socket per interface in the namespace exec enters. A socket
+// stays bound to its interface after the thread left the namespace.
+func openPacketSockets(
+	ctx context.Context,
+	exec ExecFunc,
+	interfaces []string,
+	snapLength int,
+) ([]packetSource, error) {
+	sources := make([]packetSource, 0, len(interfaces))
+	err := exec(ctx, func(ns.NetNS) error {
+		for _, name := range interfaces {
+			source, err := openPacketSocket(name, snapLength)
+			if err != nil {
+				return fmt.Errorf("interface %q: %w", name, err)
+			}
+			sources = append(sources, source)
+		}
+
+		return nil
+	})
+	if err != nil {
+		for _, source := range sources {
+			source.Close()
+		}
+
+		return nil, err
+	}
+
+	return sources, nil
+}
+
+// afpacketSource is a TPACKET_V3 receive ring on one interface.
+type afpacketSource struct {
+	handle *afpacket.TPacket
+}
+
+func openPacketSocket(name string, snapLength int) (*afpacketSource, error) {
+	// A TPACKET_V3 block holds whole frames: it must be larger than the snap length, plus the
+	// block and frame headers, and a multiple of the page size.
+	pageSize := os.Getpagesize()
+	blockSize := max(localMinBlockSize, snapLength+pageSize)
+	blockSize = (blockSize + pageSize - 1) / pageSize * pageSize
+
+	handle, err := afpacket.NewTPacket(
+		afpacket.OptInterface(name),
+		afpacket.OptTPacketVersion(afpacket.TPacketVersion3),
+		afpacket.OptFrameSize(blockSize),
+		afpacket.OptBlockSize(blockSize),
+		afpacket.OptNumBlocks(localRingBlocks),
+		afpacket.OptBlockTimeout(localBlockTimeout),
+		afpacket.OptPollTimeout(localPollTimeout),
+		// the kernel moves 802.1Q tags out of the frame; captures show them in place
+		afpacket.OptAddVLANHeader(true),
+	)
+	if err != nil {
+		return nil, err
+	}
+	// promiscuous mode is a membership of this socket and ends with it
+	if err := handle.SetPromiscuous(true); err != nil {
+		handle.Close()
+		return nil, fmt.Errorf("failed to enable promiscuous mode: %w", err)
+	}
+
+	return &afpacketSource{handle: handle}, nil
+}
+
+func (s *afpacketSource) ReadPacket() ([]byte, gopacket.CaptureInfo, error) {
+	data, info, err := s.handle.ZeroCopyReadPacketData()
+	if errors.Is(err, afpacket.ErrTimeout) {
+		return nil, info, errReadTimeout
+	}
+
+	return data, info, err
+}
+
+func (s *afpacketSource) Close() {
+	s.handle.Close()
+}
diff --git a/capture/local_test.go b/capture/local_test.go
new file mode 100644
index 0000000..f91bb00
--- /dev/null
+++ b/capture/local_test.go
@@ -0,0 +1,476 @@
+package capture
+
+import (
+	"bytes"
+	"context"
+	"errors"
+	"fmt"
+	"io"
+	"slices"
+	"strings"
+	"sync"
+	"testing"
+	"time"
+
+	"github.com/containernetworking/plugins/pkg/ns"
+	"github.com/gopacket/gopacket"
+	"github.com/gopacket/gopacket/afpacket"
+	clablabruntime "github.com/srl-labs/containerlab/labruntime"
+)
+
+// fakeFrame is one packet a fake source returns.
+type fakeFrame struct {
+	data   []byte
+	stamp  time.Time
+	length int
+	vlan   bool
+	// visible delays the frame like a ring block the kernel has not handed over yet.
+	visible time.Time
+	// err ends the source with this error instead of a packet.
+	err error
+}
+
+// fakeSource returns frames from a channel, errReadTimeout while none is queued.
+type fakeSource struct {
+	frames  chan fakeFrame
+	closed  chan struct{}
+	once    sync.Once
+	pending *fakeFrame
+}
+
+func newFakeSource() *fakeSource {
+	return &fakeSource{frames: make(chan fakeFrame, 64), closed: make(chan struct{})}
+}
+
+func (s *fakeSource) ReadPacket() ([]byte, gopacket.CaptureInfo, error) {
+	if s.pending == nil {
+		select {
+		case frame := <-s.frames:
+			s.pending = &frame
+		case <-time.After(5 * time.Millisecond):
+			return nil, gopacket.CaptureInfo{}, errReadTimeout
+		}
+	}
+	if wait := time.Until(s.pending.visible); wait > 0 {
+		time.Sleep(min(wait, 5*time.Millisecond))
+		if time.Now().Before(s.pending.visible) {
+			return nil, gopacket.CaptureInfo{}, errReadTimeout
+		}
+	}
+
+	{
+		frame := *s.pending
+		s.pending = nil
+		if frame.err != nil {
+			return nil, gopacket.CaptureInfo{}, frame.err
+		}
+		info := gopacket.CaptureInfo{
+			Timestamp: frame.stamp, CaptureLength: len(frame.data), Length: frame.length,
+		}
+		if frame.vlan {
+			info.AncillaryData = []any{afpacket.AncillaryVLAN{VLAN: 10}}
+		}
+
+		return frame.data, info, nil
+	}
+}
+
+func (s *fakeSource) Close() {
+	s.once.Do(func() { close(s.closed) })
+}
+
+// fakeHost hands out fake sources per node and interface. Opening an interface listed in
+// missing fails, like an interface whose node does not run.
+type fakeHost struct {
+	mu      sync.Mutex
+	opened  map[string][]*fakeSource
+	missing map[string]bool
+	ready   chan string
+}
+
+func newFakeHost() *fakeHost {
+	return &fakeHost{
+		opened: map[string][]*fakeSource{}, missing: map[string]bool{},
+		ready: make(chan string, 64),
+	}
+}
+
+func (h *fakeHost) exec(node string) ExecFunc {
+	return func(_ context.Context, f func(ns.NetNS) error) error {
+		h.mu.Lock()
+		missing := h.missing[node]
+		h.mu.Unlock()
+		if missing {
+			return fmt.Errorf("node %q: container network namespace is not available", node)
+		}
+
+		return f(nil)
+	}
+}
+
+func (h *fakeHost) open(
+	ctx context.Context,
+	exec ExecFunc,
+	interfaces []string,
+	_ int,
+) ([]packetSource, error) {
+	var node string
+	err := exec(ctx, func(ns.NetNS) error { return nil })
+	if err != nil {
+		return nil, err
+	}
+
+	h.mu.Lock()
+	defer h.mu.Unlock()
+	sources := make([]packetSource, 0, len(interfaces))
+	for _, name := range interfaces {
+		if h.missing[name] {
+			return nil, fmt.Errorf("interface %q: no such network interface", name)
+		}
+		node = name
+		source := newFakeSource()
+		h.opened[name] = append(h.opened[name], source)
+		sources = append(sources, source)
+		h.ready <- node
+	}
+
+	return sources, nil
+}
+
+func (h *fakeHost) source(name string, generation int) *fakeSource {
+	h.mu.Lock()
+	defer h.mu.Unlock()
+
+	return h.opened[name][generation]
+}
+
+func (h *fakeHost) setMissing(name string, missing bool) {
+	h.mu.Lock()
+	defer h.mu.Unlock()
+	h.missing[name] = missing
+}
+
+func (h *fakeHost) capture() localCapture {
+	return localCapture{
+		open:           h.open,
+		window:         20 * time.Millisecond,
+		reopenInterval: time.Millisecond,
+	}
+}
+
+// waitOpened waits until n sources were opened.
+func (h *fakeHost) waitOpened(t *testing.T, n int) {
+	t.Helper()
+	for range n {
+		select {
+		case <-h.ready:
+		case <-time.After(2 * time.Second):
+			t.Fatal("source was not opened")
+		}
+	}
+}
+
+type parsedLocalCapture struct {
+	interfaces []string
+	packets    []Packet
+}
+
+func parseLocalCapture(t *testing.T, data []byte) parsedLocalCapture {
+	t.Helper()
+
+	var parsed parsedLocalCapture
+	reader := NewReader(bytes.NewReader(data))
+	for {
+		event, err := reader.Next()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			t.Fatalf("invalid capture: %v", err)
+		}
+		if event.Interface != nil {
+			parsed.interfaces = append(parsed.interfaces, event.Interface.Name)
+		}
+		if event.Packet != nil {
+			parsed.packets = append(parsed.packets, *event.Packet)
+		}
+	}
+	if reader.Sections() != 1 {
+		t.Fatalf("capture has %d sections", reader.Sections())
+	}
+
+	return parsed
+}
+
+func localRequest(packetLimit int, duration time.Duration) clablabruntime.CaptureRequest {
+	return clablabruntime.CaptureRequest{
+		Name: "lab",
+		Targets: []clablabruntime.CaptureTarget{
+			{Node: "r1", Interface: "eth1"}, {Node: "r2", Interface: "eth1"},
+		},
+		PacketLimit: packetLimit,
+		Duration:    duration,
+		SnapLength:  64,
+	}
+}
+
+func TestCaptureLocalMergesInterfacesInTimestampOrder(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	// the sources are keyed by interface name in the fake host, so the two nodes use distinct
+	// names behind the requested ones
+	targets := []LocalTarget{
+		{Node: "r1", Interface: "e1", Exec: host.exec("r1")},
+		{Node: "r2", Interface: "e2", Exec: host.exec("r2")},
+	}
+
+	var out bytes.Buffer
+	done := make(chan error, 1)
+	go func() {
+		done <- host.capture().run(context.Background(), localRequest(4, 0), targets, &out)
+	}()
+	host.waitOpened(t, 2)
+
+	base := time.Unix(1_761_559_200, 0)
+	// r2's packets reach containerlab first although r1 stamped one of them earlier
+	host.source("e2", 0).frames <- fakeFrame{
+		data: []byte("r2-a"), stamp: base.Add(2 * time.Millisecond), length: 4,
+	}
+	host.source("e2", 0).frames <- fakeFrame{
+		data: bytes.Repeat([]byte{7}, 100), stamp: base.Add(4 * time.Millisecond), length: 100,
+	}
+	host.source("e1", 0).frames <- fakeFrame{
+		data: []byte("r1-a"), stamp: base.Add(1 * time.Millisecond), length: 4,
+	}
+	host.source("e1", 0).frames <- fakeFrame{
+		data: []byte("r1-v"), stamp: base.Add(3 * time.Millisecond), length: 60, vlan: true,
+	}
+
+	select {
+	case err := <-done:
+		if err != nil {
+			t.Fatal(err)
+		}
+	case <-time.After(5 * time.Second):
+		t.Fatal("capture did not stop at the packet limit")
+	}
+
+	parsed := parseLocalCapture(t, out.Bytes())
+	if want := []string{"r1:e1", "r2:e2"}; !slices.Equal(parsed.interfaces, want) {
+		t.Fatalf("interfaces = %v, want %v", parsed.interfaces, want)
+	}
+	if len(parsed.packets) != 4 {
+		t.Fatalf("captured %d packets, want 4", len(parsed.packets))
+	}
+	var ids []uint32
+	for idx, packet := range parsed.packets {
+		ids = append(ids, packet.InterfaceID)
+		if want := base.Add(time.Duration(idx+1) * time.Millisecond).
+			UnixNano(); packet.Timestamp != want {
+			t.Fatalf("packet %d stamped %d, want %d", idx, packet.Timestamp, want)
+		}
+	}
+	if !slices.Equal(ids, []uint32{0, 1, 0, 1}) {
+		t.Fatalf("interface IDs = %v", ids)
+	}
+	// a re-inserted VLAN tag counts toward the frame length
+	if parsed.packets[2].OriginalLength != 64 {
+		t.Fatalf("VLAN frame length = %d, want 64", parsed.packets[2].OriginalLength)
+	}
+	// frames are cut to the snap length
+	if last := parsed.packets[3]; len(last.Data) != 64 || last.OriginalLength != 100 {
+		t.Fatalf("long frame kept %d of %d bytes", len(last.Data), last.OriginalLength)
+	}
+	for _, name := range []string{"e1", "e2"} {
+		select {
+		case <-host.source(name, 0).closed:
+		default:
+			t.Fatalf("source %s was not closed", name)
+		}
+	}
+}
+
+func TestCaptureLocalEndsAfterTheDurationOrWhenCanceled(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	targets := []LocalTarget{
+		{Node: "r1", Interface: "e1", Exec: host.exec("r1")},
+		{Node: "r1", Interface: "e2", Exec: host.exec("r1")},
+	}
+
+	var out bytes.Buffer
+	start := time.Now()
+	if err := host.capture().run(context.Background(), localRequest(0, 50*time.Millisecond),
+		targets, &out); err != nil {
+		t.Fatal(err)
+	}
+	if elapsed := time.Since(start); elapsed < 50*time.Millisecond || elapsed > 2*time.Second {
+		t.Fatalf("capture ran %s for a 50ms duration", elapsed)
+	}
+	if parsed := parseLocalCapture(t, out.Bytes()); len(parsed.interfaces) != 2 {
+		t.Fatalf("interfaces = %v", parsed.interfaces)
+	}
+
+	ctx, cancel := context.WithCancel(context.Background())
+	done := make(chan error, 1)
+	go func() {
+		done <- host.capture().run(ctx, localRequest(0, 0), targets, io.Discard)
+	}()
+	host.waitOpened(t, 4)
+	cancel()
+	select {
+	case err := <-done:
+		if err != nil {
+			t.Fatalf("canceled capture returned %v", err)
+		}
+	case <-time.After(2 * time.Second):
+		t.Fatal("canceled capture did not end")
+	}
+}
+
+func TestCaptureLocalWritesPacketsStillInTheRingWhenItEnds(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	targets := []LocalTarget{{Node: "r1", Interface: "e1", Exec: host.exec("r1")}}
+	req := localRequest(0, 0)
+	req.Targets = req.Targets[:1]
+
+	ctx, cancel := context.WithCancel(context.Background())
+	var out bytes.Buffer
+	done := make(chan error, 1)
+	go func() {
+		done <- host.capture().run(ctx, req, targets, &out)
+	}()
+	host.waitOpened(t, 1)
+
+	now := time.Now()
+	// stamped before the end, handed over by the kernel only after it
+	host.source("e1", 0).frames <- fakeFrame{
+		data: []byte("before"), stamp: now, length: 6, visible: now.Add(30 * time.Millisecond),
+	}
+	// stamped after the end: not part of the capture
+	host.source("e1", 0).frames <- fakeFrame{
+		data: []byte("after"), stamp: now.Add(time.Hour), length: 5,
+		visible: now.Add(40 * time.Millisecond),
+	}
+	cancel()
+
+	if err := <-done; err != nil {
+		t.Fatal(err)
+	}
+	parsed := parseLocalCapture(t, out.Bytes())
+	if len(parsed.packets) != 1 || string(parsed.packets[0].Data) != "before" {
+		t.Fatalf("packets = %+v, want only the one stamped before the end", parsed.packets)
+	}
+}
+
+func TestCaptureLocalFailsWithoutOutputWhenAnInterfaceCannotBeOpened(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	host.setMissing("r2", true)
+	targets := []LocalTarget{
+		{Node: "r1", Interface: "e1", Exec: host.exec("r1")},
+		{Node: "r2", Interface: "e2", Exec: host.exec("r2")},
+	}
+
+	var out bytes.Buffer
+	err := host.capture().run(context.Background(), localRequest(0, 0), targets, &out)
+	if err == nil || !strings.Contains(err.Error(), `failed to start the capture on node "r2"`) {
+		t.Fatalf("error = %v", err)
+	}
+	if out.Len() != 0 {
+		t.Fatalf("wrote %d bytes before failing", out.Len())
+	}
+	select {
+	case <-host.source("e1", 0).closed:
+	default:
+		t.Fatal("the source opened before the failure was not closed")
+	}
+}
+
+func TestCaptureLocalReopensInterfacesAndReportsWhileTheyWereGone(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	targets := []LocalTarget{{Node: "r1", Interface: "e1", Exec: host.exec("r1")}}
+	req := localRequest(2, 0)
+	req.Targets = req.Targets[:1]
+
+	var mu sync.Mutex
+	var gaps []clablabruntime.CaptureGap
+	req.OnGap = func(gap clablabruntime.CaptureGap) {
+		mu.Lock()
+		defer mu.Unlock()
+		gaps = append(gaps, gap)
+	}
+
+	var out bytes.Buffer
+	done := make(chan error, 1)
+	go func() {
+		done <- host.capture().run(context.Background(), req, targets, &out)
+	}()
+	host.waitOpened(t, 1)
+
+	base := time.Unix(1_761_559_200, 0)
+	host.source("e1", 0).frames <- fakeFrame{data: []byte("a"), stamp: base, length: 1}
+
+	// the interface goes down: the socket fails and is reopened at once, without a gap
+	host.source("e1", 0).frames <- fakeFrame{err: afpacket.ErrPoll}
+	host.waitOpened(t, 1)
+
+	// the node restarts: the interface is gone for a while, then back
+	host.setMissing("r1", true)
+	host.source("e1", 1).frames <- fakeFrame{err: afpacket.ErrPoll}
+	time.Sleep(20 * time.Millisecond)
+	host.setMissing("r1", false)
+	host.waitOpened(t, 1)
+	host.source("e1", 2).frames <- fakeFrame{
+		data: []byte("b"), stamp: base.Add(time.Second), length: 1,
+	}
+
+	select {
+	case err := <-done:
+		if err != nil {
+			t.Fatal(err)
+		}
+	case <-time.After(5 * time.Second):
+		t.Fatal("capture did not stop at the packet limit")
+	}
+
+	if parsed := parseLocalCapture(t, out.Bytes()); len(parsed.packets) != 2 {
+		t.Fatalf("captured %d packets across the reopen, want 2", len(parsed.packets))
+	}
+	mu.Lock()
+	defer mu.Unlock()
+	if len(gaps) != 1 {
+		t.Fatalf("gaps = %+v, want one for the restart", gaps)
+	}
+	gap := gaps[0]
+	if gap.Node != "r1" || !slices.Equal(gap.Interfaces, []string{"e1"}) || gap.To.IsZero() ||
+		!gap.To.After(gap.From) || !strings.Contains(gap.Reason, "not available") {
+		t.Fatalf("gap = %+v", gap)
+	}
+}
+
+func TestCaptureLocalChecksTheRequest(t *testing.T) {
+	t.Parallel()
+
+	host := newFakeHost()
+	targets := []LocalTarget{{Node: "r1", Interface: "e1", Exec: host.exec("r1")}}
+
+	req := localRequest(0, 0)
+	req.SnapLength = 10
+	if err := host.capture().run(context.Background(), req, targets[:1], io.Discard); err == nil ||
+		!strings.Contains(err.Error(), "snap length 10") {
+		t.Fatalf("small snap length: error = %v", err)
+	}
+
+	if err := host.capture().run(context.Background(), localRequest(0, 0), targets,
+		io.Discard); err == nil || !strings.Contains(err.Error(), "1 resolved targets for 2") {
+		t.Fatalf("target mismatch: error = %v", err)
+	}
+}
diff --git a/capture/output.go b/capture/output.go
new file mode 100644
index 0000000..574c33a
--- /dev/null
+++ b/capture/output.go
@@ -0,0 +1,203 @@
+package capture
+
+import (
+	"context"
+	"fmt"
+	"io"
+	"strings"
+	"sync/atomic"
+	"time"
+
+	"github.com/charmbracelet/log"
+	clablabruntime "github.com/srl-labs/containerlab/labruntime"
+)
+
+// Snap length bounds of a capture.
+const (
+	// DefaultSnapLength is the snap length of a request without one.
+	DefaultSnapLength = 256 << 10
+	MinSnapLength     = 64
+	MaxSnapLength     = 1 << 20
+)
+
+// ValidateRequest checks the bounds of a capture request and fills the default snap length.
+func ValidateRequest(req *clablabruntime.CaptureRequest) error {
+	if req.Name == "" {
+		return fmt.Errorf("topology name is required")
+	}
+	if len(req.Targets) == 0 {
+		return fmt.Errorf("at least one capture target (node and interface) is required")
+	}
+	for _, target := range req.Targets {
+		if target.Node == "" || target.Interface == "" {
+			return fmt.Errorf("capture target %+v needs a node and an interface", target)
+		}
+	}
+	if req.Duration < 0 {
+		return fmt.Errorf("capture duration must not be negative")
+	}
+	if req.PacketLimit < 0 {
+		return fmt.Errorf("capture packet limit must not be negative")
+	}
+	if req.SnapLength == 0 {
+		req.SnapLength = DefaultSnapLength
+	}
+	if req.SnapLength < MinSnapLength || req.SnapLength > MaxSnapLength {
+		return fmt.Errorf("capture snap length %d is outside %d to %d bytes", req.SnapLength,
+			MinSnapLength, MaxSnapLength)
+	}
+
+	return nil
+}
+
+// FindInterface matches a requested interface by its name, then by its alias.
+func FindInterface(
+	entries []clablabruntime.CaptureInterface,
+	name string,
+) (clablabruntime.CaptureInterface, bool) {
+	for _, entry := range entries {
+		if entry.Interface == name {
+			return entry, true
+		}
+	}
+	for _, entry := range entries {
+		if entry.Alias != "" && entry.Alias == name {
+			return entry, true
+		}
+	}
+
+	return clablabruntime.CaptureInterface{}, false
+}
+
+// DescribeInterfaces lists interfaces for an error message: name (alias), ...
+func DescribeInterfaces(entries []clablabruntime.CaptureInterface) string {
+	if len(entries) == 0 {
+		return "none"
+	}
+
+	names := make([]string, 0, len(entries))
+	for _, entry := range entries {
+		name := entry.Interface
+		if entry.Alias != "" {
+			name += " (" + entry.Alias + ")"
+		}
+		names = append(names, name)
+	}
+
+	return strings.Join(names, ", ")
+}
+
+// ReportGap hands a gap to onGap, or logs it as a warning when onGap is nil.
+func ReportGap(onGap func(clablabruntime.CaptureGap), gap clablabruntime.CaptureGap) {
+	if onGap != nil {
+		onGap(gap)
+		return
+	}
+
+	to := "unknown"
+	if !gap.To.IsZero() {
+		to = gap.To.Format(time.RFC3339Nano)
+	}
+	log.Warn("Capture has a gap", "node", gap.Node, "interfaces", strings.Join(gap.Interfaces, ","),
+		"from", gap.From.Format(time.RFC3339Nano), "to", to, "reason", gap.Reason)
+}
+
+// Output is the merged pcapng stream of one capture: the section header with one interface per
+// capture target, then the packets of every target in timestamp order (through a Reorder), up
+// to an optional packet limit.
+type Output struct {
+	writer  *Writer
+	reorder *Reorder
+	limit   int64
+	written atomic.Int64
+	stop    func()
+
+	cancelRun context.CancelFunc
+	runDone   chan struct{}
+}
+
+// NewOutput writes the section header and one Interface Description Block per name to w, then
+// starts the reorder buffer with the given window (zero or less writes packets as they come).
+// stop is called once the packet limit is reached or a write failed. Close must be called.
+func NewOutput(
+	w io.Writer,
+	names []string,
+	snapLength, packetLimit int,
+	window time.Duration,
+	stop func(),
+) (*Output, error) {
+	writer := NewWriter(w)
+	if err := writer.WriteHeader(
+		names,
+		uint32(snapLength),
+	); err != nil { //nolint:gosec // validated
+		return nil, err
+	}
+
+	out := &Output{
+		writer:  writer,
+		reorder: NewReorder(window, writer.WritePacket, stop),
+		limit:   int64(packetLimit),
+		stop:    stop,
+		runDone: make(chan struct{}),
+	}
+
+	var runCtx context.Context
+	runCtx, out.cancelRun = context.WithCancel(context.Background())
+	go func() {
+		defer close(out.runDone)
+		out.reorder.Run(runCtx)
+	}()
+
+	return out, nil
+}
+
+// Emit hands a packet of the interface with the given index to the stream. It reports false
+// once the packet limit is reached and the capture stops, and returns the error of a failed
+// write.
+func (o *Output) Emit(id uint32, packet *Packet) (bool, error) {
+	if o.limit > 0 {
+		count := o.written.Add(1)
+		if count > o.limit {
+			o.stop()
+			return false, nil
+		}
+		if err := o.reorder.Push(id, packet); err != nil {
+			return false, err
+		}
+		if count == o.limit {
+			o.stop()
+			return false, nil
+		}
+
+		return true, nil
+	}
+
+	o.written.Add(1)
+
+	return true, o.reorder.Push(id, packet)
+}
+
+// Written returns the number of packets handed to the stream so far.
+func (o *Output) Written() int64 {
+	return o.written.Load()
+}
+
+// Hold keeps packets stamped after timestamp back until Release(key).
+func (o *Output) Hold(key any, timestamp int64) {
+	o.reorder.Hold(key, timestamp)
+}
+
+// Release removes the hold of key.
+func (o *Output) Release(key any) {
+	o.reorder.Release(key)
+}
+
+// Close writes the packets still held back and returns the first write error.
+func (o *Output) Close() error {
+	o.cancelRun()
+	<-o.runDone
+	o.reorder.Flush()
+
+	return o.writer.Err()
+}
diff --git a/capture/pcapng.go b/capture/pcapng.go
new file mode 100644
index 0000000..246ac84
--- /dev/null
+++ b/capture/pcapng.go
@@ -0,0 +1,333 @@
+// Package capture writes the pcapng streams of `containerlab capture`: one section with one
+// interface per capture target, packets merged across targets in timestamp order. The local
+// capturer reads lab link interfaces of Docker and Podman nodes through packet sockets; the c9s
+// lab runtime feeds the same writer from clabwire streams.
+package capture
+
+import (
+	"bufio"
+	"encoding/binary"
+	"errors"
+	"fmt"
+	"io"
+	"math"
+	"sync"
+)
+
+// pcapng block layout (https://www.ietf.org/archive/id/draft-ietf-opsawg-pcapng-03.html). clabwire
+// writes little-endian sections, and so does the merged stream containerlab writes.
+const (
+	pcapngSectionHeaderType  = 0x0a0d0d0a
+	pcapngInterfaceType      = 0x00000001
+	pcapngEnhancedPacketType = 0x00000006
+	pcapngByteOrderMagic     = 0x1a2b3c4d
+	pcapngOptionEnd          = 0
+	pcapngOptionUserAppl     = 4
+	pcapngOptionIfName       = 2
+	pcapngOptionIfTSResol    = 9
+	pcapngLinkTypeEthernet   = 1
+	// pcapngNanoseconds is the if_tsresol value for 10^-9 s resolution.
+	pcapngNanoseconds = 9
+	// pcapngMaxBlockLength bounds a block read from a capture stream: a packet of the largest
+	// clabwire snap length (1 MiB) plus framing.
+	pcapngMaxBlockLength = 1<<20 + 1024
+	// captureUserApplication names the writer in the merged section header.
+	captureUserApplication = "containerlab"
+)
+
+var errPCAPNGByteOrder = errors.New("pcapng section is not little-endian")
+
+// InterfaceDescription is an Interface Description Block.
+type InterfaceDescription struct {
+	LinkType   uint16
+	SnapLength uint32
+	Name       string
+	// TSResol is the raw if_tsresol value; 6 (microseconds) when the block has none.
+	TSResol byte
+}
+
+// Packet is an Enhanced Packet Block with its timestamp in nanoseconds.
+type Packet struct {
+	InterfaceID    uint32
+	Timestamp      int64
+	OriginalLength uint32
+	Data           []byte
+}
+
+// Reader reads the blocks of a pcapng stream as clabwire writes it: one or more
+// little-endian sections, each with its Interface Description Blocks before its packets.
+type Reader struct {
+	r          *bufio.Reader
+	interfaces []InterfaceDescription
+	// sections counts the Section Header Blocks read so far.
+	sections int
+}
+
+// NewReader returns a reader of the pcapng stream r.
+func NewReader(r io.Reader) *Reader {
+	return &Reader{r: bufio.NewReaderSize(r, 64<<10)}
+}
+
+// Sections returns the number of Section Header Blocks read so far.
+func (p *Reader) Sections() int {
+	return p.sections
+}
+
+// Event is one block of interest: a new interface or a packet.
+type Event struct {
+	Interface *InterfaceDescription
+	Packet    *Packet
+}
+
+// Next returns the next interface or packet, skipping other block types. It returns io.EOF at
+// the clean end of the stream, and io.ErrUnexpectedEOF for a stream cut inside a block.
+func (p *Reader) Next() (Event, error) {
+	for {
+		var header [8]byte
+		if _, err := io.ReadFull(p.r, header[:]); err != nil {
+			if errors.Is(err, io.EOF) {
+				return Event{}, io.EOF
+			}
+
+			return Event{}, io.ErrUnexpectedEOF
+		}
+
+		blockType := binary.LittleEndian.Uint32(header[0:4])
+		length := binary.LittleEndian.Uint32(header[4:8])
+		if blockType == pcapngSectionHeaderType {
+			// the byte-order magic tells a big-endian section apart before its length is
+			// trusted: that length reads byte swapped
+			magic, err := p.r.Peek(4)
+			if err != nil {
+				return Event{}, io.ErrUnexpectedEOF
+			}
+			if binary.BigEndian.Uint32(magic) == pcapngByteOrderMagic {
+				return Event{}, errPCAPNGByteOrder
+			}
+		}
+		if length < 12 || length%4 != 0 || length > pcapngMaxBlockLength {
+			return Event{}, fmt.Errorf("invalid pcapng block length %d (at most %d)", length,
+				pcapngMaxBlockLength)
+		}
+
+		body := make([]byte, length-8)
+		if _, err := io.ReadFull(p.r, body); err != nil {
+			return Event{}, io.ErrUnexpectedEOF
+		}
+		if binary.LittleEndian.Uint32(body[len(body)-4:]) != length {
+			return Event{}, fmt.Errorf("pcapng block lengths do not match")
+		}
+		body = body[:len(body)-4]
+
+		switch blockType {
+		case pcapngSectionHeaderType:
+			if len(body) < 16 {
+				return Event{}, fmt.Errorf("short pcapng section header")
+			}
+			if binary.LittleEndian.Uint32(body[0:4]) != pcapngByteOrderMagic {
+				return Event{}, errPCAPNGByteOrder
+			}
+			p.sections++
+			p.interfaces = nil
+		case pcapngInterfaceType:
+			if p.sections == 0 {
+				return Event{}, fmt.Errorf("pcapng interface before a section header")
+			}
+			intf, err := parsePCAPNGInterface(body)
+			if err != nil {
+				return Event{}, err
+			}
+			p.interfaces = append(p.interfaces, intf)
+
+			return Event{Interface: &p.interfaces[len(p.interfaces)-1]}, nil
+		case pcapngEnhancedPacketType:
+			packet, err := p.parsePacket(body)
+			if err != nil {
+				return Event{}, err
+			}
+
+			return Event{Packet: &packet}, nil
+		}
+	}
+}
+
+func parsePCAPNGInterface(body []byte) (InterfaceDescription, error) {
+	if len(body) < 8 {
+		return InterfaceDescription{}, fmt.Errorf("short pcapng interface description")
+	}
+	intf := InterfaceDescription{
+		LinkType:   binary.LittleEndian.Uint16(body[0:2]),
+		SnapLength: binary.LittleEndian.Uint32(body[4:8]),
+		TSResol:    6,
+	}
+
+	options := body[8:]
+	for len(options) >= 4 {
+		code := binary.LittleEndian.Uint16(options[0:2])
+		size := int(binary.LittleEndian.Uint16(options[2:4]))
+		if code == pcapngOptionEnd {
+			break
+		}
+		padded := size + pcapngPadding(size)
+		if 4+padded > len(options) {
+			return InterfaceDescription{}, fmt.Errorf("truncated pcapng interface option")
+		}
+		value := options[4 : 4+size]
+		switch code {
+		case pcapngOptionIfName:
+			intf.Name = string(value)
+		case pcapngOptionIfTSResol:
+			if size == 1 {
+				intf.TSResol = value[0]
+			}
+		}
+		options = options[4+padded:]
+	}
+
+	return intf, nil
+}
+
+func (p *Reader) parsePacket(body []byte) (Packet, error) {
+	if len(body) < 20 {
+		return Packet{}, fmt.Errorf("short pcapng enhanced packet")
+	}
+	packet := Packet{
+		InterfaceID:    binary.LittleEndian.Uint32(body[0:4]),
+		OriginalLength: binary.LittleEndian.Uint32(body[16:20]),
+	}
+	if int(packet.InterfaceID) >= len(p.interfaces) {
+		return Packet{}, fmt.Errorf("pcapng packet for undeclared interface %d",
+			packet.InterfaceID)
+	}
+	captured := binary.LittleEndian.Uint32(body[12:16])
+	if int(captured) > len(body)-20 {
+		return Packet{}, fmt.Errorf("pcapng packet data exceeds its block")
+	}
+	packet.Data = body[20 : 20+captured]
+
+	raw := uint64(binary.LittleEndian.Uint32(body[4:8]))<<32 |
+		uint64(binary.LittleEndian.Uint32(body[8:12]))
+	timestamp, err := pcapngNanosecondsFrom(raw, p.interfaces[packet.InterfaceID].TSResol)
+	if err != nil {
+		return Packet{}, err
+	}
+	packet.Timestamp = timestamp
+
+	return packet, nil
+}
+
+// pcapngNanosecondsFrom converts a timestamp in an interface's resolution to nanoseconds.
+// Only decimal resolutions up to nanoseconds occur in clabwire streams.
+func pcapngNanosecondsFrom(raw uint64, tsresol byte) (int64, error) {
+	if tsresol&0x80 != 0 || tsresol > pcapngNanoseconds {
+		return 0, fmt.Errorf("unsupported pcapng timestamp resolution %#x", tsresol)
+	}
+	scale := uint64(1)
+	for range pcapngNanoseconds - int(tsresol) {
+		scale *= 10
+	}
+	if raw > math.MaxInt64/scale {
+		return 0, fmt.Errorf("pcapng timestamp out of range")
+	}
+
+	return int64(raw * scale), nil //nolint:gosec // bounded above
+}
+
+// Writer writes one little-endian section with nanosecond timestamps. Every block goes out
+// in one Write under a lock, so concurrent writers never interleave blocks and a stream cut
+// between writes is still a valid capture.
+type Writer struct {
+	mu  sync.Mutex
+	w   io.Writer
+	err error
+}
+
+// NewWriter returns a writer of one pcapng section to w.
+func NewWriter(w io.Writer) *Writer {
+	return &Writer{w: w}
+}
+
+// WriteHeader writes the Section Header Block and one Interface Description Block per name, in
+// order; packets refer to the interfaces by that index.
+func (p *Writer) WriteHeader(names []string, snapLength uint32) error {
+	section := make([]byte, 16)
+	binary.LittleEndian.PutUint32(section[0:], pcapngByteOrderMagic)
+	binary.LittleEndian.PutUint16(section[4:], 1)
+	binary.LittleEndian.PutUint16(section[6:], 0)
+	binary.LittleEndian.PutUint64(section[8:], math.MaxUint64)
+	section = appendPCAPNGOption(section, pcapngOptionUserAppl, []byte(captureUserApplication))
+	section = appendPCAPNGOption(section, pcapngOptionEnd, nil)
+
+	header := pcapngBlock(pcapngSectionHeaderType, section)
+	for _, name := range names {
+		description := make([]byte, 8)
+		binary.LittleEndian.PutUint16(description[0:], pcapngLinkTypeEthernet)
+		binary.LittleEndian.PutUint32(description[4:], snapLength)
+		description = appendPCAPNGOption(description, pcapngOptionIfName, []byte(name))
+		description = appendPCAPNGOption(description, pcapngOptionIfTSResol,
+			[]byte{pcapngNanoseconds})
+		description = appendPCAPNGOption(description, pcapngOptionEnd, nil)
+		header = append(header, pcapngBlock(pcapngInterfaceType, description)...)
+	}
+
+	return p.write(header)
+}
+
+// WritePacket writes an Enhanced Packet Block for the interface with the given index.
+func (p *Writer) WritePacket(interfaceID uint32, packet *Packet) error {
+	timestamp := uint64(packet.Timestamp) //nolint:gosec // capture timestamps are positive
+	body := make([]byte, 20, 20+len(packet.Data)+3)
+	binary.LittleEndian.PutUint32(body[0:], interfaceID)
+	binary.LittleEndian.PutUint32(body[4:], uint32(timestamp>>32))
+	binary.LittleEndian.PutUint32(body[8:], uint32(timestamp)) //nolint:gosec // low 32 bits
+	binary.LittleEndian.PutUint32(body[12:], uint32(len(packet.Data)))
+	binary.LittleEndian.PutUint32(body[16:], packet.OriginalLength)
+	body = append(body, packet.Data...)
+	body = append(body, make([]byte, pcapngPadding(len(packet.Data)))...)
+
+	return p.write(pcapngBlock(pcapngEnhancedPacketType, body))
+}
+
+// Err returns the first write error, or nil.
+func (p *Writer) Err() error {
+	p.mu.Lock()
+	defer p.mu.Unlock()
+
+	return p.err
+}
+
+func (p *Writer) write(block []byte) error {
+	p.mu.Lock()
+	defer p.mu.Unlock()
+
+	if p.err != nil {
+		return p.err
+	}
+	if _, err := p.w.Write(block); err != nil {
+		p.err = fmt.Errorf("failed to write the capture: %w", err)
+	}
+
+	return p.err
+}
+
+func pcapngBlock(blockType uint32, body []byte) []byte {
+	total := uint32(12 + len(body)) //nolint:gosec // bounded by the snap length
+	block := make([]byte, 8, total)
+	binary.LittleEndian.PutUint32(block[0:], blockType)
+	binary.LittleEndian.PutUint32(block[4:], total)
+	block = append(block, body...)
+
+	return binary.LittleEndian.AppendUint32(block, total)
+}
+
+func appendPCAPNGOption(body []byte, code uint16, value []byte) []byte {
+	body = binary.LittleEndian.AppendUint16(body, code)
+	body = binary.LittleEndian.AppendUint16(body, uint16(len(value))) //nolint:gosec // short
+	body = append(body, value...)
+
+	return append(body, make([]byte, pcapngPadding(len(value)))...)
+}
+
+func pcapngPadding(length int) int {
+	return (4 - length%4) % 4
+}
diff --git a/capture/pcapng_test.go b/capture/pcapng_test.go
new file mode 100644
index 0000000..0917d16
--- /dev/null
+++ b/capture/pcapng_test.go
@@ -0,0 +1,167 @@
+package capture
+
+import (
+	"bytes"
+	"encoding/binary"
+	"errors"
+	"io"
+	"strings"
+	"testing"
+)
+
+func TestPCAPNGWriterAndReaderRoundTrip(t *testing.T) {
+	t.Parallel()
+
+	var out bytes.Buffer
+	writer := NewWriter(&out)
+	if err := writer.WriteHeader([]string{"r1:e1-1", "r2:eth1"}, 1500); err != nil {
+		t.Fatal(err)
+	}
+	packets := []Packet{
+		{
+			InterfaceID:    1,
+			Timestamp:      1_761_559_200_123_456_789,
+			OriginalLength: 98,
+			Data:           []byte("abcde"),
+		},
+		{
+			InterfaceID:    0,
+			Timestamp:      1_761_559_200_123_456_790,
+			OriginalLength: 4,
+			Data:           []byte("wxyz"),
+		},
+	}
+	for idx := range packets {
+		if err := writer.WritePacket(packets[idx].InterfaceID, &packets[idx]); err != nil {
+			t.Fatal(err)
+		}
+	}
+
+	data := out.Bytes()
+	// the section header names the writer
+	if !bytes.Contains(data[:64], []byte(captureUserApplication)) {
+		t.Fatal("section header has no shb_userappl")
+	}
+	if len(data)%4 != 0 {
+		t.Fatalf("stream length %d is not 32-bit aligned", len(data))
+	}
+
+	reader := NewReader(bytes.NewReader(data))
+	var names []string
+	var read []Packet
+	for {
+		event, err := reader.Next()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			t.Fatal(err)
+		}
+		if event.Interface != nil {
+			names = append(names, event.Interface.Name)
+			if event.Interface.SnapLength != 1500 || event.Interface.LinkType != 1 {
+				t.Fatalf("interface = %+v", event.Interface)
+			}
+		}
+		if event.Packet != nil {
+			read = append(read, *event.Packet)
+		}
+	}
+	if len(names) != 2 || names[0] != "r1:e1-1" || names[1] != "r2:eth1" {
+		t.Fatalf("names = %v", names)
+	}
+	for idx := range packets {
+		if read[idx].InterfaceID != packets[idx].InterfaceID ||
+			read[idx].Timestamp != packets[idx].Timestamp ||
+			read[idx].OriginalLength != packets[idx].OriginalLength ||
+			!bytes.Equal(read[idx].Data, packets[idx].Data) {
+			t.Fatalf("packet %d = %+v, want %+v", idx, read[idx], packets[idx])
+		}
+	}
+}
+
+func TestPCAPNGReaderHandlesRepeatedSectionsAndResolutions(t *testing.T) {
+	t.Parallel()
+
+	var out bytes.Buffer
+	first := NewWriter(&out)
+	_ = first.WriteHeader([]string{"eth1"}, 64)
+	_ = first.WritePacket(0, &Packet{Timestamp: 5, Data: []byte{1}})
+
+	// a second section whose interface has microsecond timestamps (no if_tsresol)
+	section := make([]byte, 16)
+	binary.LittleEndian.PutUint32(section[0:], pcapngByteOrderMagic)
+	binary.LittleEndian.PutUint16(section[4:], 1)
+	out.Write(pcapngBlock(pcapngSectionHeaderType, section))
+	description := make([]byte, 8)
+	binary.LittleEndian.PutUint16(description[0:], 1)
+	description = appendPCAPNGOption(description, pcapngOptionIfName, []byte("eth2"))
+	out.Write(pcapngBlock(pcapngInterfaceType, description))
+	body := make([]byte, 20)
+	binary.LittleEndian.PutUint32(body[8:], 7) // 7 microseconds
+	out.Write(pcapngBlock(pcapngEnhancedPacketType, body))
+
+	reader := NewReader(&out)
+	var timestamps []int64
+	for {
+		event, err := reader.Next()
+		if errors.Is(err, io.EOF) {
+			break
+		}
+		if err != nil {
+			t.Fatal(err)
+		}
+		if event.Packet != nil {
+			timestamps = append(timestamps, event.Packet.Timestamp)
+		}
+	}
+	if reader.sections != 2 || len(timestamps) != 2 || timestamps[0] != 5 || timestamps[1] != 7000 {
+		t.Fatalf("sections %d, timestamps %v", reader.sections, timestamps)
+	}
+}
+
+func TestPCAPNGReaderRejectsInvalidStreams(t *testing.T) {
+	t.Parallel()
+
+	var valid bytes.Buffer
+	writer := NewWriter(&valid)
+	_ = writer.WriteHeader([]string{"eth1"}, 64)
+	_ = writer.WritePacket(0, &Packet{Timestamp: 1, Data: []byte("data")})
+
+	readAll := func(data []byte) error {
+		reader := NewReader(bytes.NewReader(data))
+		for {
+			_, err := reader.Next()
+			if errors.Is(err, io.EOF) {
+				return nil
+			}
+			if err != nil {
+				return err
+			}
+		}
+	}
+
+	if err := readAll(valid.Bytes()[:valid.Len()-6]); !errors.Is(err, io.ErrUnexpectedEOF) {
+		t.Fatalf("truncated stream: %v", err)
+	}
+
+	bigEndian := append([]byte(nil), valid.Bytes()...)
+	binary.BigEndian.PutUint32(bigEndian[4:], binary.LittleEndian.Uint32(bigEndian[4:]))
+	binary.BigEndian.PutUint32(bigEndian[8:], pcapngByteOrderMagic)
+	if err := readAll(bigEndian); !errors.Is(err, errPCAPNGByteOrder) {
+		t.Fatalf("big-endian section: %v", err)
+	}
+
+	// a little-endian section header longer than the reader accepts is not a byte-order error
+	oversized := append([]byte(nil), valid.Bytes()...)
+	binary.LittleEndian.PutUint32(oversized[4:], 2<<20)
+	if err := readAll(oversized); err == nil || errors.Is(err, errPCAPNGByteOrder) ||
+		!strings.Contains(err.Error(), "invalid pcapng block length") {
+		t.Fatalf("oversized little-endian section: %v", err)
+	}
+
+	packetFirst := pcapngBlock(pcapngEnhancedPacketType, make([]byte, 20))
+	if err := readAll(packetFirst); err == nil {
+		t.Fatal("packet before any interface accepted")
+	}
+}
diff --git a/capture/reorder.go b/capture/reorder.go
new file mode 100644
index 0000000..277ba1a
--- /dev/null
+++ b/capture/reorder.go
@@ -0,0 +1,271 @@
+package capture
+
+import (
+	"container/heap"
+	"context"
+	"sync"
+	"time"
+
+	"github.com/charmbracelet/log"
+)
+
+// maxReorderBytes bounds the packet data the reorder buffer holds. Past it, the oldest packets
+// are written early, which can put them out of order.
+const maxReorderBytes = 64 << 20
+
+// Reorder writes the packets of several capture sources in timestamp order.
+//
+// Each source (a node's capture stream, or a local interface socket) delivers its packets with
+// its own delay. The buffer holds every packet for `window` after it arrived and writes the held
+// packets in timestamp order, so a packet that was stamped earlier but delivered up to `window`

+// later still goes out first. A packet stamped before the last packet written arrived too late
+// to be ordered: it is written as it comes and counted, and the count goes to the debug log when
+// the capture ends.
+//
+// A source can place a hold at the earliest timestamp it may still write (Hold); packets stamped
+// after a hold wait for it to be released (Release). The c9s runtime holds while it switches
+// between chained capture segments.
+type Reorder struct {
+	write  func(id uint32, packet *Packet) error
+	onFail func()
+	window time.Duration
+	now    func() time.Time
+
+	mu     sync.Mutex
+	queue  reorderQueue
+	bytes  int
+	seq    uint64
+	holds  map[any]int64
+	err    error
+	wake   chan struct{}
+	stats  reorderStats
+	cursor int64 // timestamp of the latest packet written in order
+}
+
+type reorderStats struct {
+	late    int
+	maxLate time.Duration
+	forced  int
+}
+
+// reorderedPacket is a packet waiting in the buffer.
+type reorderedPacket struct {
+	id      uint32
+	packet  *Packet
+	arrived time.Time
+	seq     uint64
+}
+
+// reorderQueue is a min-heap by timestamp, then arrival.
+type reorderQueue []reorderedPacket
+
+func (q reorderQueue) Len() int { return len(q) }
+
+func (q reorderQueue) Less(i, j int) bool {
+	if q[i].packet.Timestamp != q[j].packet.Timestamp {
+		return q[i].packet.Timestamp < q[j].packet.Timestamp
+	}
+
+	return q[i].seq < q[j].seq
+}
+
+func (q reorderQueue) Swap(i, j int) { q[i], q[j] = q[j], q[i] }
+
+func (q *reorderQueue) Push(
+	x any,
+) {
+	*q = append(*q, x.(reorderedPacket))
+} //nolint:forcetypeassert // heap contract
+
+func (q *reorderQueue) Pop() any {
+	old := *q
+	item := old[len(old)-1]
+	*q = old[:len(old)-1]
+
+	return item
+}
+
+// NewReorder returns a buffer that writes through write; onFail is called once a write
+// failed. A window of zero or less writes every packet as it arrives.
+func NewReorder(
+	window time.Duration,
+	write func(id uint32, packet *Packet) error,
+	onFail func(),
+) *Reorder {
+	return &Reorder{
+		write: write, onFail: onFail, window: window, now: time.Now,
+		holds: map[any]int64{}, wake: make(chan struct{}, 1),
+	}
+}
+
+// push hands a packet to the buffer. It returns the error of a failed write.
+func (q *Reorder) Push(id uint32, packet *Packet) error {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	if q.err != nil {
+		return q.err
+	}
+	if q.window <= 0 {
+		return q.writeLocked(id, packet)
+	}
+	if q.cursor != 0 && packet.Timestamp < q.cursor {
+		q.stats.late++
+		q.stats.maxLate = max(q.stats.maxLate, time.Duration(q.cursor-packet.Timestamp))
+		if q.stats.late == 1 {
+			log.Debug("Capture packet arrived after the reorder window, writing it out of order",
+				"late_by", time.Duration(q.cursor-packet.Timestamp), "window", q.window)
+		}
+
+		return q.writeLocked(id, packet)
+	}
+
+	q.seq++
+	heap.Push(&q.queue, reorderedPacket{id: id, packet: packet, arrived: q.now(), seq: q.seq})
+	q.bytes += len(packet.Data)
+	for q.bytes > maxReorderBytes && q.queue.Len() > 0 {
+		q.stats.forced++
+		if err := q.popLocked(); err != nil {
+			return err
+		}
+	}
+
+	select {
+	case q.wake <- struct{}{}:
+	default:
+	}
+
+	return nil
+}
+
+// hold keeps packets stamped after timestamp in the buffer until release(key).
+func (q *Reorder) Hold(key any, timestamp int64) {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	q.holds[key] = timestamp
+}
+
+// release removes the hold of key.
+func (q *Reorder) Release(key any) {
+	q.mu.Lock()
+	_, held := q.holds[key]
+	delete(q.holds, key)
+	q.mu.Unlock()
+
+	if held {
+		select {
+		case q.wake <- struct{}{}:
+		default:
+		}
+	}
+}
+
+// run writes due packets until ctx ends.
+func (q *Reorder) Run(ctx context.Context) {
+	if q.window <= 0 {
+		return
+	}
+
+	timer := time.NewTimer(time.Hour)
+	defer timer.Stop()
+
+	for {
+		next := q.writeDue()
+		wait := time.Hour
+		if !next.IsZero() {
+			wait = max(next.Sub(q.now()), time.Millisecond)
+		}
+		resetTimer(timer, wait)
+
+		select {
+		case <-ctx.Done():
+			return
+		case <-q.wake:
+		case <-timer.C:
+		}
+	}
+}
+
+// writeDue writes the packets that waited for the window and are not behind a hold, in
+// timestamp order. It returns when the next packet is due, or zero when that depends on a new
+// packet or a released hold.
+func (q *Reorder) writeDue() time.Time {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	held, limit := false, int64(0)
+	for _, timestamp := range q.holds {
+		if !held || timestamp < limit {
+			held, limit = true, timestamp
+		}
+	}
+
+	now := q.now()
+	for q.queue.Len() > 0 && q.err == nil {
+		head := q.queue[0]
+		if held && head.packet.Timestamp > limit {
+			return time.Time{}
+		}
+		if due := head.arrived.Add(q.window); due.After(now) {
+			return due
+		}
+		if q.popLocked() != nil {
+			return time.Time{}
+		}
+	}
+
+	return time.Time{}
+}
+
+// flush writes every remaining packet in timestamp order and logs what could not be ordered.
+func (q *Reorder) Flush() {
+	q.mu.Lock()
+	defer q.mu.Unlock()
+
+	for q.queue.Len() > 0 && q.err == nil {
+		if q.popLocked() != nil {
+			break
+		}
+	}
+	q.queue, q.bytes = nil, 0
+
+	if q.stats.late > 0 || q.stats.forced > 0 {
+		log.Debug("Capture wrote packets out of timestamp order",
+			"late_packets", q.stats.late, "max_late_by", q.stats.maxLate,
+			"window", q.window, "buffer_overflow_packets", q.stats.forced)
+	}
+}
+
+func (q *Reorder) popLocked() error {
+	item := heap.Pop(&q.queue).(reorderedPacket) //nolint:forcetypeassert // heap contract
+	q.bytes -= len(item.packet.Data)
+	q.cursor = max(q.cursor, item.packet.Timestamp)
+
+	return q.writeLocked(item.id, item.packet)
+}
+
+func (q *Reorder) writeLocked(id uint32, packet *Packet) error {
+	if err := q.write(id, packet); err != nil {
+		if q.err == nil {
+			q.err = err
+			if q.onFail != nil {
+				q.onFail()
+			}
+		}
+
+		return err
+	}
+
+	return nil
+}
+
+func resetTimer(timer *time.Timer, d time.Duration) {
+	if !timer.Stop() {
+		select {
+		case <-timer.C:
+		default:
+		}
+	}
+	timer.Reset(d)
+}
diff --git a/capture/reorder_test.go b/capture/reorder_test.go
new file mode 100644
index 0000000..d281bed
--- /dev/null
+++ b/capture/reorder_test.go
@@ -0,0 +1,202 @@
+package capture
+
+import (
+	"context"
+	"errors"
+	"slices"
+	"sync"
+	"testing"
+	"time"
+)
+
+// reorderSink records what a reorder buffer writes.
+type reorderSink struct {
+	mu      sync.Mutex
+	written []int64
+	ids     []uint32
+	failAt  int
+}
+
+func (s *reorderSink) write(id uint32, packet *Packet) error {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+	if s.failAt > 0 && len(s.written) == s.failAt {
+		return errors.New("write |1: broken pipe")
+	}
+	s.written = append(s.written, packet.Timestamp)
+	s.ids = append(s.ids, id)
+
+	return nil
+}
+
+func (s *reorderSink) timestamps() []int64 {
+	s.mu.Lock()
+	defer s.mu.Unlock()
+
+	return slices.Clone(s.written)
+}
+
+// interleavedStreams pushes two synthetic streams of ticks, interleaved in time: stream 0 is
+// delivered at once, stream 1 `delay` after its packets were stamped. Both stamp a packet every
+// 2 ms, offset by 1 ms.
+func interleavedStreams(t *testing.T, q *Reorder, ticks int, delay time.Duration) {
+	t.Helper()
+
+	start := time.Now()
+	type delivery struct {
+		at time.Time
+		id uint32
+		ts int64
+	}
+	var deliveries []delivery
+	for tick := range ticks {
+		stamp := start.Add(time.Duration(tick) * 2 * time.Millisecond)
+		deliveries = append(deliveries,
+			delivery{at: stamp, id: 0, ts: stamp.UnixNano()},
+			delivery{
+				at: stamp.Add(time.Millisecond + delay), id: 1,
+				ts: stamp.Add(time.Millisecond).UnixNano(),
+			})
+	}
+	slices.SortStableFunc(deliveries, func(a, b delivery) int { return a.at.Compare(b.at) })
+
+	for _, next := range deliveries {
+		time.Sleep(time.Until(next.at))
+		if err := q.Push(
+			next.id,
+			&Packet{InterfaceID: next.id, Timestamp: next.ts},
+		); err != nil {
+			t.Fatal(err)
+		}
+	}
+}
+
+func runReorder(q *Reorder) func() {
+	ctx, cancel := context.WithCancel(context.Background())
+	done := make(chan struct{})
+	go func() {
+		defer close(done)
+		q.Run(ctx)
+	}()
+
+	return func() {
+		cancel()
+		<-done
+		q.Flush()
+	}
+}
+
+func TestReorderOrdersStreamsWithinTheWindow(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(100*time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	interleavedStreams(t, q, 60, 40*time.Millisecond)
+
+	// packets go out while the capture runs, not only at the end
+	time.Sleep(150 * time.Millisecond)
+	if len(sink.timestamps()) == 0 {
+		t.Fatal("nothing written while the streams ran")
+	}
+	stop()
+
+	written := sink.timestamps()
+	if len(written) != 120 || !slices.IsSorted(written) {
+		t.Fatalf("written %d packets, sorted %v", len(written), slices.IsSorted(written))
+	}
+	if q.stats.late != 0 {
+		t.Fatalf("late packets = %d", q.stats.late)
+	}
+}
+
+func TestReorderWritesLatePacketsAsTheyCome(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(20*time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	// stream 1 arrives 80 ms after its stamps, far beyond the 20 ms window
+	interleavedStreams(t, q, 60, 80*time.Millisecond)
+	stop()
+
+	written := sink.timestamps()
+	if len(written) != 120 {
+		t.Fatalf("written %d packets, want all 120", len(written))
+	}
+	if q.stats.late == 0 || q.stats.maxLate < 40*time.Millisecond || slices.IsSorted(written) {
+		t.Fatalf("late = %d (max %s), sorted %v; want late packets written out of order",
+			q.stats.late, q.stats.maxLate, slices.IsSorted(written))
+	}
+}
+
+func TestReorderHoldsPacketsAfterAHold(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(time.Millisecond, sink.write, nil)
+	stop := runReorder(q)
+	defer stop()
+
+	chain := &struct{ name string }{"chain"}
+	q.Hold(chain, 100)
+	for _, ts := range []int64{50, 150, 100, 200} {
+		if err := q.Push(0, &Packet{Timestamp: ts}); err != nil {
+			t.Fatal(err)
+		}
+	}
+	time.Sleep(30 * time.Millisecond)
+	if got := sink.timestamps(); !slices.Equal(got, []int64{50, 100}) {
+		t.Fatalf("written under the hold = %v, want [50 100]", got)
+	}
+
+	// the chain writes what it held back, then releases
+	if err := q.Push(1, &Packet{Timestamp: 120}); err != nil {
+		t.Fatal(err)
+	}
+	q.Release(chain)
+	time.Sleep(30 * time.Millisecond)
+	if got := sink.timestamps(); !slices.Equal(got, []int64{50, 100, 120, 150, 200}) {
+		t.Fatalf("written after the release = %v", got)
+	}
+}
+
+func TestReorderStopsAtTheFirstWriteError(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{failAt: 2}
+	failed := 0
+	q := NewReorder(time.Millisecond, sink.write, func() { failed++ })
+	stop := runReorder(q)
+
+	var err error
+	for ts := int64(1); ts < 50 && err == nil; ts++ {
+		err = q.Push(0, &Packet{Timestamp: ts})
+		time.Sleep(2 * time.Millisecond)
+	}
+	stop()
+
+	if err == nil || failed != 1 || len(sink.timestamps()) != 2 {
+		t.Fatalf(
+			"push error = %v, onFail calls %d, written %d",
+			err,
+			failed,
+			len(sink.timestamps()),
+		)
+	}
+}
+
+func TestReorderWithoutWindowWritesThrough(t *testing.T) {
+	t.Parallel()
+
+	sink := &reorderSink{}
+	q := NewReorder(0, sink.write, nil)
+	for _, ts := range []int64{30, 10, 20} {
+		if err := q.Push(0, &Packet{Timestamp: ts}); err != nil {
+			t.Fatal(err)
+		}
+	}
+	if got := sink.timestamps(); !slices.Equal(got, []int64{30, 10, 20}) {
+		t.Fatalf("written = %v, want arrival order", got)
+	}
+}
