// Package capture writes the pcapng streams of `containerlab capture`: one section with one
// interface per capture target, packets merged across targets in timestamp order. The local
// capturer reads lab link interfaces of Docker and Podman nodes through packet sockets; the c9s
// lab runtime feeds the same writer from clabwire streams.
package capture

import (
	"bufio"
	"encoding/binary"
	"errors"
	"fmt"
	"io"
	"math"
	"sync"
)

// pcapng block layout (https://www.ietf.org/archive/id/draft-ietf-opsawg-pcapng-03.html). clabwire
// writes little-endian sections, and so does the merged stream containerlab writes.
const (
	pcapngSectionHeaderType  = 0x0a0d0d0a
	pcapngInterfaceType      = 0x00000001
	pcapngEnhancedPacketType = 0x00000006
	pcapngByteOrderMagic     = 0x1a2b3c4d
	pcapngOptionEnd          = 0
	pcapngOptionUserAppl     = 4
	pcapngOptionIfName       = 2
	pcapngOptionIfTSResol    = 9
	pcapngLinkTypeEthernet   = 1
	// pcapngNanoseconds is the if_tsresol value for 10^-9 s resolution.
	pcapngNanoseconds = 9
	// pcapngMaxBlockLength bounds a block read from a capture stream: a packet of the largest
	// clabwire snap length (1 MiB) plus framing.
	pcapngMaxBlockLength = 1<<20 + 1024
	// captureUserApplication names the writer in the merged section header.
	captureUserApplication = "containerlab"
)

var errPCAPNGByteOrder = errors.New("pcapng section is not little-endian")

// InterfaceDescription is an Interface Description Block.
type InterfaceDescription struct {
	LinkType   uint16
	SnapLength uint32
	Name       string
	// TSResol is the raw if_tsresol value; 6 (microseconds) when the block has none.
	TSResol byte
}

// Packet is an Enhanced Packet Block with its timestamp in nanoseconds.
type Packet struct {
	InterfaceID    uint32
	Timestamp      int64
	OriginalLength uint32
	Data           []byte
}

// Reader reads the blocks of a pcapng stream as clabwire writes it: one or more
// little-endian sections, each with its Interface Description Blocks before its packets.
type Reader struct {
	r          *bufio.Reader
	interfaces []InterfaceDescription
	// sections counts the Section Header Blocks read so far.
	sections int
}

// NewReader returns a reader of the pcapng stream r.
func NewReader(r io.Reader) *Reader {
	return &Reader{r: bufio.NewReaderSize(r, 64<<10)}
}

// Sections returns the number of Section Header Blocks read so far.
func (p *Reader) Sections() int {
	return p.sections
}

// Event is one block of interest: a new interface or a packet.
type Event struct {
	Interface *InterfaceDescription
	Packet    *Packet
}

// Next returns the next interface or packet, skipping other block types. It returns io.EOF at
// the clean end of the stream, and io.ErrUnexpectedEOF for a stream cut inside a block.
func (p *Reader) Next() (Event, error) {
	for {
		var header [8]byte
		if _, err := io.ReadFull(p.r, header[:]); err != nil {
			if errors.Is(err, io.EOF) {
				return Event{}, io.EOF
			}

			return Event{}, io.ErrUnexpectedEOF
		}

		blockType := binary.LittleEndian.Uint32(header[0:4])
		length := binary.LittleEndian.Uint32(header[4:8])
		if blockType == pcapngSectionHeaderType {
			// the byte-order magic tells a big-endian section apart before its length is
			// trusted: that length reads byte swapped
			magic, err := p.r.Peek(4)
			if err != nil {
				return Event{}, io.ErrUnexpectedEOF
			}
			if binary.BigEndian.Uint32(magic) == pcapngByteOrderMagic {
				return Event{}, errPCAPNGByteOrder
			}
		}
		if length < 12 || length%4 != 0 || length > pcapngMaxBlockLength {
			return Event{}, fmt.Errorf("invalid pcapng block length %d (at most %d)", length,
				pcapngMaxBlockLength)
		}

		body := make([]byte, length-8)
		if _, err := io.ReadFull(p.r, body); err != nil {
			return Event{}, io.ErrUnexpectedEOF
		}
		if binary.LittleEndian.Uint32(body[len(body)-4:]) != length {
			return Event{}, fmt.Errorf("pcapng block lengths do not match")
		}
		body = body[:len(body)-4]

		switch blockType {
		case pcapngSectionHeaderType:
			if len(body) < 16 {
				return Event{}, fmt.Errorf("short pcapng section header")
			}
			if binary.LittleEndian.Uint32(body[0:4]) != pcapngByteOrderMagic {
				return Event{}, errPCAPNGByteOrder
			}
			p.sections++
			p.interfaces = nil
		case pcapngInterfaceType:
			if p.sections == 0 {
				return Event{}, fmt.Errorf("pcapng interface before a section header")
			}
			intf, err := parsePCAPNGInterface(body)
			if err != nil {
				return Event{}, err
			}
			p.interfaces = append(p.interfaces, intf)

			return Event{Interface: &p.interfaces[len(p.interfaces)-1]}, nil
		case pcapngEnhancedPacketType:
			packet, err := p.parsePacket(body)
			if err != nil {
				return Event{}, err
			}

			return Event{Packet: &packet}, nil
		}
	}
}

func parsePCAPNGInterface(body []byte) (InterfaceDescription, error) {
	if len(body) < 8 {
		return InterfaceDescription{}, fmt.Errorf("short pcapng interface description")
	}
	intf := InterfaceDescription{
		LinkType:   binary.LittleEndian.Uint16(body[0:2]),
		SnapLength: binary.LittleEndian.Uint32(body[4:8]),
		TSResol:    6,
	}

	options := body[8:]
	for len(options) >= 4 {
		code := binary.LittleEndian.Uint16(options[0:2])
		size := int(binary.LittleEndian.Uint16(options[2:4]))
		if code == pcapngOptionEnd {
			break
		}
		padded := size + pcapngPadding(size)
		if 4+padded > len(options) {
			return InterfaceDescription{}, fmt.Errorf("truncated pcapng interface option")
		}
		value := options[4 : 4+size]
		switch code {
		case pcapngOptionIfName:
			intf.Name = string(value)
		case pcapngOptionIfTSResol:
			if size == 1 {
				intf.TSResol = value[0]
			}
		}
		options = options[4+padded:]
	}

	return intf, nil
}

func (p *Reader) parsePacket(body []byte) (Packet, error) {
	if len(body) < 20 {
		return Packet{}, fmt.Errorf("short pcapng enhanced packet")
	}
	packet := Packet{
		InterfaceID:    binary.LittleEndian.Uint32(body[0:4]),
		OriginalLength: binary.LittleEndian.Uint32(body[16:20]),
	}
	if int(packet.InterfaceID) >= len(p.interfaces) {
		return Packet{}, fmt.Errorf("pcapng packet for undeclared interface %d",
			packet.InterfaceID)
	}
	captured := binary.LittleEndian.Uint32(body[12:16])
	if int(captured) > len(body)-20 {
		return Packet{}, fmt.Errorf("pcapng packet data exceeds its block")
	}
	packet.Data = body[20 : 20+captured]

	raw := uint64(binary.LittleEndian.Uint32(body[4:8]))<<32 |
		uint64(binary.LittleEndian.Uint32(body[8:12]))
	timestamp, err := pcapngNanosecondsFrom(raw, p.interfaces[packet.InterfaceID].TSResol)
	if err != nil {
		return Packet{}, err
	}
	packet.Timestamp = timestamp

	return packet, nil
}

// pcapngNanosecondsFrom converts a timestamp in an interface's resolution to nanoseconds.
// Only decimal resolutions up to nanoseconds occur in clabwire streams.
func pcapngNanosecondsFrom(raw uint64, tsresol byte) (int64, error) {
	if tsresol&0x80 != 0 || tsresol > pcapngNanoseconds {
		return 0, fmt.Errorf("unsupported pcapng timestamp resolution %#x", tsresol)
	}
	scale := uint64(1)
	for range pcapngNanoseconds - int(tsresol) {
		scale *= 10
	}
	if raw > math.MaxInt64/scale {
		return 0, fmt.Errorf("pcapng timestamp out of range")
	}

	return int64(raw * scale), nil //nolint:gosec // bounded above
}

// Writer writes one little-endian section with nanosecond timestamps. Every block goes out
// in one Write under a lock, so concurrent writers never interleave blocks and a stream cut
// between writes is still a valid capture.
type Writer struct {
	mu  sync.Mutex
	w   io.Writer
	err error
}

// NewWriter returns a writer of one pcapng section to w.
func NewWriter(w io.Writer) *Writer {
	return &Writer{w: w}
}

// WriteHeader writes the Section Header Block and one Interface Description Block per name, in
// order; packets refer to the interfaces by that index.
func (p *Writer) WriteHeader(names []string, snapLength uint32) error {
	section := make([]byte, 16)
	binary.LittleEndian.PutUint32(section[0:], pcapngByteOrderMagic)
	binary.LittleEndian.PutUint16(section[4:], 1)
	binary.LittleEndian.PutUint16(section[6:], 0)
	binary.LittleEndian.PutUint64(section[8:], math.MaxUint64)
	section = appendPCAPNGOption(section, pcapngOptionUserAppl, []byte(captureUserApplication))
	section = appendPCAPNGOption(section, pcapngOptionEnd, nil)

	header := pcapngBlock(pcapngSectionHeaderType, section)
	for _, name := range names {
		description := make([]byte, 8)
		binary.LittleEndian.PutUint16(description[0:], pcapngLinkTypeEthernet)
		binary.LittleEndian.PutUint32(description[4:], snapLength)
		description = appendPCAPNGOption(description, pcapngOptionIfName, []byte(name))
		description = appendPCAPNGOption(description, pcapngOptionIfTSResol,
			[]byte{pcapngNanoseconds})
		description = appendPCAPNGOption(description, pcapngOptionEnd, nil)
		header = append(header, pcapngBlock(pcapngInterfaceType, description)...)
	}

	return p.write(header)
}

// WritePacket writes an Enhanced Packet Block for the interface with the given index.
func (p *Writer) WritePacket(interfaceID uint32, packet *Packet) error {
	timestamp := uint64(packet.Timestamp) //nolint:gosec // capture timestamps are positive
	body := make([]byte, 20, 20+len(packet.Data)+3)
	binary.LittleEndian.PutUint32(body[0:], interfaceID)
	binary.LittleEndian.PutUint32(body[4:], uint32(timestamp>>32))
	binary.LittleEndian.PutUint32(body[8:], uint32(timestamp)) //nolint:gosec // low 32 bits
	binary.LittleEndian.PutUint32(body[12:], uint32(len(packet.Data)))
	binary.LittleEndian.PutUint32(body[16:], packet.OriginalLength)
	body = append(body, packet.Data...)
	body = append(body, make([]byte, pcapngPadding(len(packet.Data)))...)

	return p.write(pcapngBlock(pcapngEnhancedPacketType, body))
}

// Err returns the first write error, or nil.
func (p *Writer) Err() error {
	p.mu.Lock()
	defer p.mu.Unlock()

	return p.err
}

func (p *Writer) write(block []byte) error {
	p.mu.Lock()
	defer p.mu.Unlock()

	if p.err != nil {
		return p.err
	}
	if _, err := p.w.Write(block); err != nil {
		p.err = fmt.Errorf("failed to write the capture: %w", err)
	}

	return p.err
}

func pcapngBlock(blockType uint32, body []byte) []byte {
	total := uint32(12 + len(body)) //nolint:gosec // bounded by the snap length
	block := make([]byte, 8, total)
	binary.LittleEndian.PutUint32(block[0:], blockType)
	binary.LittleEndian.PutUint32(block[4:], total)
	block = append(block, body...)

	return binary.LittleEndian.AppendUint32(block, total)
}

func appendPCAPNGOption(body []byte, code uint16, value []byte) []byte {
	body = binary.LittleEndian.AppendUint16(body, code)
	body = binary.LittleEndian.AppendUint16(body, uint16(len(value))) //nolint:gosec // short
	body = append(body, value...)

	return append(body, make([]byte, pcapngPadding(len(value)))...)
}

func pcapngPadding(length int) int {
	return (4 - length%4) % 4
}

package capture

import (
	"context"
	"fmt"
	"io"
	"strings"
	"sync/atomic"
	"time"

	"github.com/charmbracelet/log"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
)

// Snap length bounds of a capture.
const (
	// DefaultSnapLength is the snap length of a request without one.
	DefaultSnapLength = 256 << 10
	MinSnapLength     = 64
	MaxSnapLength     = 1 << 20
)

// ValidateRequest checks the bounds of a capture request and fills the default snap length.
func ValidateRequest(req *clablabruntime.CaptureRequest) error {
	if req.Name == "" {
		return fmt.Errorf("topology name is required")
	}
	if len(req.Targets) == 0 {
		return fmt.Errorf("at least one capture target (node and interface) is required")
	}
	for _, target := range req.Targets {
		if target.Node == "" || target.Interface == "" {
			return fmt.Errorf("capture target %+v needs a node and an interface", target)
		}
	}
	if req.Duration < 0 {
		return fmt.Errorf("capture duration must not be negative")
	}
	if req.PacketLimit < 0 {
		return fmt.Errorf("capture packet limit must not be negative")
	}
	if req.SnapLength == 0 {
		req.SnapLength = DefaultSnapLength
	}
	if req.SnapLength < MinSnapLength || req.SnapLength > MaxSnapLength {
		return fmt.Errorf("capture snap length %d is outside %d to %d bytes", req.SnapLength,
			MinSnapLength, MaxSnapLength)
	}

	return nil
}

// FindInterface matches a requested interface by its name, then by its alias.
func FindInterface(
	entries []clablabruntime.CaptureInterface,
	name string,
) (clablabruntime.CaptureInterface, bool) {
	for _, entry := range entries {
		if entry.Interface == name {
			return entry, true
		}
	}
	for _, entry := range entries {
		if entry.Alias != "" && entry.Alias == name {
			return entry, true
		}
	}

	return clablabruntime.CaptureInterface{}, false
}

// DescribeInterfaces lists interfaces for an error message: name (alias), ...
func DescribeInterfaces(entries []clablabruntime.CaptureInterface) string {
	if len(entries) == 0 {
		return "none"
	}

	names := make([]string, 0, len(entries))
	for _, entry := range entries {
		name := entry.Interface
		if entry.Alias != "" {
			name += " (" + entry.Alias + ")"
		}
		names = append(names, name)
	}

	return strings.Join(names, ", ")
}

// ReportGap hands a gap to onGap, or logs it as a warning when onGap is nil.
func ReportGap(onGap func(clablabruntime.CaptureGap), gap clablabruntime.CaptureGap) {
	if onGap != nil {
		onGap(gap)
		return
	}

	to := "unknown"
	if !gap.To.IsZero() {
		to = gap.To.Format(time.RFC3339Nano)
	}
	log.Warn("Capture has a gap", "node", gap.Node, "interfaces", strings.Join(gap.Interfaces, ","),
		"from", gap.From.Format(time.RFC3339Nano), "to", to, "reason", gap.Reason)
}

// Output is the merged pcapng stream of one capture: the section header with one interface per
// capture target, then the packets of every target in timestamp order (through a Reorder), up
// to an optional packet limit.
type Output struct {
	writer  *Writer
	reorder *Reorder
	limit   int64
	written atomic.Int64
	stop    func()

	cancelRun context.CancelFunc
	runDone   chan struct{}
}

// NewOutput writes the section header and one Interface Description Block per name to w, then
// starts the reorder buffer with the given window (zero or less writes packets as they come).
// stop is called once the packet limit is reached or a write failed. Close must be called.
func NewOutput(
	w io.Writer,
	names []string,
	snapLength, packetLimit int,
	window time.Duration,
	stop func(),
) (*Output, error) {
	writer := NewWriter(w)
	if err := writer.WriteHeader(
		names,
		uint32(snapLength),
	); err != nil { //nolint:gosec // validated
		return nil, err
	}

	out := &Output{
		writer:  writer,
		reorder: NewReorder(window, writer.WritePacket, stop),
		limit:   int64(packetLimit),
		stop:    stop,
		runDone: make(chan struct{}),
	}

	var runCtx context.Context
	runCtx, out.cancelRun = context.WithCancel(context.Background())
	go func() {
		defer close(out.runDone)
		out.reorder.Run(runCtx)
	}()

	return out, nil
}

// Emit hands a packet of the interface with the given index to the stream. It reports false
// once the packet limit is reached and the capture stops, and returns the error of a failed
// write.
func (o *Output) Emit(id uint32, packet *Packet) (bool, error) {
	if o.limit > 0 {
		count := o.written.Add(1)
		if count > o.limit {
			o.stop()
			return false, nil
		}
		if err := o.reorder.Push(id, packet); err != nil {
			return false, err
		}
		if count == o.limit {
			o.stop()
			return false, nil
		}

		return true, nil
	}

	o.written.Add(1)

	return true, o.reorder.Push(id, packet)
}

// Written returns the number of packets handed to the stream so far.
func (o *Output) Written() int64 {
	return o.written.Load()
}

// Hold keeps packets stamped after timestamp back until Release(key).
func (o *Output) Hold(key any, timestamp int64) {
	o.reorder.Hold(key, timestamp)
}

// Release removes the hold of key.
func (o *Output) Release(key any) {
	o.reorder.Release(key)
}

// Close writes the packets still held back and returns the first write error.
func (o *Output) Close() error {
	o.cancelRun()
	<-o.runDone
	o.reorder.Flush()

	return o.writer.Err()
}

package cmd

import (
	"encoding/json"
	"fmt"
	"io"
	"os"
	"strings"
	"time"

	"github.com/charmbracelet/log"
	tableWriter "github.com/jedib0t/go-pretty/v6/table"
	"github.com/jedib0t/go-pretty/v6/text"
	"github.com/spf13/cobra"
	clabconstants "github.com/srl-labs/containerlab/constants"
	clabcore "github.com/srl-labs/containerlab/core"
	clablabruntime "github.com/srl-labs/containerlab/labruntime"
	clabutils "github.com/srl-labs/containerlab/utils"
)

// CaptureOptions are the flags of the capture command.
type CaptureOptions struct {
	Targets     []string
	Duration    time.Duration
	PacketLimit int
	SnapLength  int
	Write       string
	List        bool
	Format      string
}

func captureCmd(o *Options) (*cobra.Command, error) {
	c := &cobra.Command{
		Use:   "capture",
		Short: "capture packets on lab link interfaces",
		Long: "capture packets on lab link interfaces of one or more nodes into one pcapng " +
			"stream\nreference: https://containerlab.dev/cmd/capture/",
		PreRunE: func(_ *cobra.Command, _ []string) error {
			if commandSkipsRoot(o.Global.Runtime) {
				return nil
			}

			// Docker and Podman captures open packet sockets in the nodes' namespaces
			return clabutils.CheckAndGetRootPrivs()
		},
		SilenceUsage: true,
		RunE: func(cmd *cobra.Command, _ []string) error {
			return captureFn(cmd, o)
		},
	}

	c.Flags().StringArrayVar(
		&o.Capture.Targets,
		"target",
		o.Capture.Targets,
		"node and interfaces to capture, as <node>:<interface>[,<interface>...]; repeatable",
	)
	c.Flags().DurationVar(
		&o.Capture.Duration,
		"duration",
		o.Capture.Duration,
		"stop after this duration; 0 captures until interrupted",
	)
	c.Flags().IntVar(
		&o.Capture.PacketLimit,
		"packet-limit",
		o.Capture.PacketLimit,
		"stop after this many packets across all targets; 0 means no limit",
	)
	c.Flags().IntVar(
		&o.Capture.SnapLength,
		"snap-length",
		o.Capture.SnapLength,
		"bytes kept of each packet (64 to 1048576); 0 uses the runtime default",
	)
	c.Flags().StringVarP(
		&o.Capture.Write,
		"write",
		"w",
		o.Capture.Write,
		"pcapng output file; - writes to stdout",
	)
	c.Flags().BoolVar(
		&o.Capture.List,
		"list",
		o.Capture.List,
		"list the capturable interfaces instead of capturing",
	)
	c.Flags().StringVarP(
		&o.Capture.Format,
		"format",
		"f",
		o.Capture.Format,
		"output format of --list: table or json",
	)

	c.Example = `# Capture e1-1 of srl1 and e1-1 of srl2 for 30 seconds into one file
containerlab capture -t srl.clab.yml --target srl1:e1-1 --target srl2:e1-1 \
  --duration 30s -w srl.pcapng

# Capture two interfaces of one node and watch them live in Wireshark
containerlab capture --name srl --target srl1:e1-1,e1-2 -w - | wireshark -k -i -

# List the interfaces capture accepts
containerlab capture --name srl --list -f json

# Capture a lab running on the c9s runtime
containerlab -r c9s capture --name srl --target srl1:e1-1 -w srl.pcapng`

	return c, nil
}

func captureFn(cmd *cobra.Command, o *Options) error {
	if o.Global.TopologyName == "" && o.Global.TopologyFile == "" {
		return fmt.Errorf("provide either a lab name (--name) or a topology file path (--topo)")
	}

	if o.Capture.List {
		return captureListFn(cmd, o)
	}

	targets, err := parseCaptureTargets(o.Capture.Targets)
	if err != nil {
		return err
	}

	c, err := clabcore.NewContainerLab(o.ToClabOptions()...)
	if err != nil {
		return err
	}

	// An interrupt ends the capture; the command still finishes the file and exits cleanly.
	// Armed before the file is created, so an interrupt never leaves it empty.
	o.Global.FinishOnCancel.Store(true)
	defer o.Global.FinishOnCancel.Store(false)

	output := cmd.OutOrStdout()
	if o.Capture.Write != "" && o.Capture.Write != "-" {
		file, err := os.Create(o.Capture.Write)
		if err != nil {
			return fmt.Errorf("failed to create the capture file: %w", err)
		}
		defer file.Close()
		output = file

		// the file belongs to the user who ran the command, also through sudo or setuid
		if err := clabutils.SetUIDAndGID(o.Capture.Write); err != nil {
			log.Debug("Cannot hand the capture file to the user", "file", o.Capture.Write,
				"error", err)
		}
	}

	err = c.Capture(cmd.Context(), clablabruntime.CaptureRequest{
		Targets:     targets,
		Duration:    o.Capture.Duration,
		PacketLimit: o.Capture.PacketLimit,
		SnapLength:  o.Capture.SnapLength,
	}, output)
	if err != nil {
		return err
	}

	if file, ok := output.(*os.File); ok && output != cmd.OutOrStdout() {
		if err := file.Sync(); err != nil {
			return fmt.Errorf("failed to write the capture file: %w", err)
		}
	}

	return nil
}

// parseCaptureTargets parses --target values: <node>:<interface>[,<interface>...]. The node name
// ends at the first colon, so interface names may contain colons or slashes.
func parseCaptureTargets(values []string) ([]clablabruntime.CaptureTarget, error) {
	if len(values) == 0 {
		return nil, fmt.Errorf("provide at least one --target <node>:<interface>[,<interface>...]")
	}

	targets := make([]clablabruntime.CaptureTarget, 0, len(values))
	for _, value := range values {
		node, interfaces, ok := strings.Cut(strings.TrimSpace(value), ":")
		node = strings.TrimSpace(node)
		if !ok || node == "" || strings.TrimSpace(interfaces) == "" {
			return nil, fmt.Errorf("invalid --target %q: use <node>:<interface>[,<interface>...]",
				value)
		}

		for _, name := range strings.Split(interfaces, ",") {
			name = strings.TrimSpace(name)
			if name == "" {
				return nil, fmt.Errorf("invalid --target %q: empty interface name", value)
			}
			targets = append(targets, clablabruntime.CaptureTarget{Node: node, Interface: name})
		}
	}

	return targets, nil
}

func captureListFn(cmd *cobra.Command, o *Options) error {
	format := o.Capture.Format
	if format == "" {
		format = clabconstants.FormatTable
	}
	if format != clabconstants.FormatTable && format != clabconstants.FormatJSON {
		return fmt.Errorf("output format %q is not supported, use 'table' or 'json'", format)
	}
	if len(o.Capture.Targets) != 0 {
		return fmt.Errorf("--list lists every running node's interfaces; it takes no --target")
	}

	c, err := clabcore.NewContainerLab(o.ToClabOptions()...)
	if err != nil {
		return err
	}

	interfaces, err := c.CaptureInterfaces(cmd.Context())
	if err != nil {
		return err
	}

	return printCaptureInterfaces(cmd.OutOrStdout(), interfaces, format)
}

func printCaptureInterfaces(
	w io.Writer,
	interfaces []clablabruntime.CaptureInterface,
	format string,
) error {
	if format == clabconstants.FormatJSON {
		if interfaces == nil {
			interfaces = []clablabruntime.CaptureInterface{}
		}
		data, err := json.MarshalIndent(interfaces, "", "  ")
		if err != nil {
			return err
		}
		_, err = fmt.Fprintln(w, string(data))

		return err
	}

	table := tableWriter.NewWriter()
	table.SetOutputMirror(w)
	table.SetStyle(tableWriter.StyleRounded)
	table.Style().Format.Header = text.FormatTitle
	table.Style().Format.HeaderAlign = text.AlignCenter
	table.AppendHeader(tableWriter.Row{"Node", "Interface", "Alias", "Peer Node", "Peer Interface"})
	table.SetColumnConfigs([]tableWriter.ColumnConfig{{Number: 1, AutoMerge: true}})
	for _, intf := range interfaces {
		alias := intf.Alias
		if alias == "" {
			alias = clabconstants.NotApplicable
		}
		table.AppendRow(tableWriter.Row{
			intf.Node, intf.Interface, alias, intf.PeerNode, intf.PeerInterface,
		})
	}
	table.Render()

	return nil
}

